#!/usr/bin/env node
// Generated by Cursor
// Updates "Last day of validity" in permit docx files to match permit page expiry dates,
// then converts to PDF and copies to app/assets/documents/

const fs = require('fs')
const path = require('path')
const { execSync } = require('child_process')
const AdmZip = require('adm-zip')

const PERMIT_EXPIRY = {
  '25GBIMPABS719': '08/03/2026',
  '25GBIMPSTYXH1': '09/03/2026',
  '25GBIMPEFPJOB': '09/03/2026',
  '25GBIMPSTYHNO': '10/03/2026',
  '25GBIMPUVWOFM': '10/03/2026',
  '25GBIMPWX0N12': '10/03/2026',
  '25GBIMPYZOPGY': '11/03/2026',
  '25GBIMPABZPMT': '11/03/2026',
  '25GBIMPCDO2DA': '11/03/2026',
  '25GBIMPGHAQTG': '11/03/2026'
}

const SRC_DIR = path.join(__dirname, '..', 'app', 'assets', 'source-permits')
const DST_DIR = path.join(__dirname, '..', 'app', 'assets', 'documents')
const TEMP_DIR = path.join(__dirname, '..', '.temp-permit-docx')

function updateDocxDate (docxPath, newDate) {
  const zip = new AdmZip(docxPath)
  const docEntry = zip.getEntry('word/document.xml')
  if (!docEntry) throw new Error('word/document.xml not found')
  let xml = docEntry.getData().toString('utf8')
  const datePattern = /\d{2}\/\d{2}\/\d{4}/
  const match = xml.match(datePattern)
  if (!match) throw new Error('No date found in document.xml')
  xml = xml.replace(match[0], newDate)
  zip.updateFile('word/document.xml', Buffer.from(xml, 'utf8'))
  return zip
}

function convertToPdf (docxPath, pdfPath) {
  try {
    const outDir = path.dirname(pdfPath)
    execSync(`soffice --headless --convert-to pdf --outdir "${outDir}" "${docxPath}"`, { stdio: 'pipe' })
    const base = path.basename(docxPath, '.docx')
    const converted = path.join(outDir, `${base}.pdf`)
    return fs.existsSync(converted)
  } catch (e) {
    // LibreOffice not found
  }
  return false
}

function main () {
  if (!fs.existsSync(SRC_DIR)) {
    console.error('Source folder not found:', SRC_DIR)
    process.exit(1)
  }
  fs.mkdirSync(TEMP_DIR, { recursive: true })
  fs.mkdirSync(DST_DIR, { recursive: true })

  for (const [ref, date] of Object.entries(PERMIT_EXPIRY)) {
    const srcDocx = path.join(SRC_DIR, `${ref}.docx`)
    const dstPdf = path.join(DST_DIR, `${ref}.pdf`)
    if (!fs.existsSync(srcDocx)) {
      console.warn('Skip', ref, '- docx not found')
      continue
    }
    const zip = updateDocxDate(srcDocx, date)
    const updatedDocx = path.join(SRC_DIR, `${ref}.docx`)
    zip.writeZip(updatedDocx)

    if (convertToPdf(updatedDocx, dstPdf)) {
      console.log('OK', ref, '->', date, '(PDF updated)')
    } else {
      console.log('Updated', ref, '->', date, '(export to PDF from Word)')
    }
  }

  try {
    fs.rmSync(TEMP_DIR, { recursive: true })
  } catch (_) {}
}

main()
